package com.heavendoor.ultralab;
import org.junit.Test;
import static org.junit.Assert.*;
public class UltraComfortStateTest {
 private static void ready(UltraComfortState s){for(long t=1000;t<=3000;t+=100){s.sample(0,255,400,false,t);s.sample(1,2,10,false,t);s.sample(2,9,30,false,t);}}
 @Test public void singleReadFailureDoesNotBlinkFreshTemperature(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);s.sample(0,260,400,false,1100);int event=s.packet(1100)[7];s.sample(0,-1,400,false,1200);assertEquals(260,s.packet(1200)[2]);assertEquals(event,s.packet(1200)[7]);s.sample(0,260,400,false,1300);assertEquals(event,s.packet(1300)[7]);assertEquals(2300,s.packet(1300)[10]);}
 @Test public void readFailureCannotExtendFreshnessOrReopenExpiredPopup(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);s.sample(0,260,400,false,1100);for(long t=1200;t<=2000;t+=100)s.sample(0,-1,400,false,t);assertEquals(-1,s.packet(2000)[2]);assertEquals(0,s.packet(2000)[10]);s.sample(0,270,400,false,2100);assertEquals(270,s.packet(2100)[2]);assertEquals(0,s.packet(2100)[7]);assertEquals(0,s.packet(2100)[10]);}
 @Test public void initialSeedNeverFabricatesUserAction(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);s.sample(1,2,10,false,1000);s.sample(2,9,30,false,1000);int[] p=s.packet(1000);assertEquals(255,p[2]);assertEquals(2,p[3]);assertEquals(9,p[5]);for(int i=7;i<13;i++)assertEquals(0,p[i]);}
 @Test public void realChangeAndRepeatsHaveBoundedLifetime(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);s.sample(0,260,400,false,1100);int serial=s.packet(1100)[7];assertTrue(serial!=0);assertEquals(2500,s.packet(1100)[10]);s.sample(0,260,400,false,1200);assertEquals(serial,s.packet(1200)[7]);assertEquals(2400,s.packet(1200)[10]);s.sample(0,260,400,false,3599);assertEquals(0,s.packet(3600)[10]);}
 @Test public void leftKindsAndRightVolumeGetOrderedSeparateEvents(){UltraComfortState s=new UltraComfortState();ready(s);s.sample(0,260,400,false,3010);s.sample(1,3,10,false,3020);s.sample(2,10,30,false,3030);int[] p=s.packet(3030);assertTrue(p[7]<p[8]&&p[8]<p[9]);assertEquals(260,p[2]);assertEquals(3,p[3]);assertEquals(10,p[5]);}
 @Test public void muteAndThemeDoNotConfusePhysicalVolume(){UltraComfortState s=new UltraComfortState();ready(s);s.sample(2,9,30,true,3010);int event=s.packet(3010)[9];assertTrue(event!=0);assertEquals(9,s.packet(3010)[5]);s.night(true);assertEquals(3,s.packet(3020)[1]);assertEquals(event,s.packet(3020)[9]);}
 @Test public void startupRouteVolumeAndMuteChangesOnlySeed(){UltraComfortState s=new UltraComfortState();for(long t=1000;t<=3300;t+=100){int value=t<1200?0:t<2900?9:12;s.sample(2,value,30,t<1400,t);assertEquals(0,s.packet(t)[9]);assertEquals(0,s.packet(t)[12]);}s.sample(2,13,30,false,3400);assertTrue(s.packet(3400)[9]>0);assertEquals(2500,s.packet(3400)[12]);}
 @Test public void reconnectAndStaleRecoveryRebuildMediaBaseline(){UltraComfortState s=new UltraComfortState();ready(s);s.sample(2,10,30,false,3100);assertTrue(s.packet(3100)[9]>0);s.reset();for(long t=4000;t<=6000;t+=100)s.sample(2,t<4200?0:11,30,false,t);assertEquals(0,s.packet(6000)[9]);s.sample(2,12,30,false,6100);assertTrue(s.packet(6100)[9]>0);s.sample(2,3,30,false,7000);assertEquals(0,s.packet(7000)[9]);}
 @Test public void temperatureAndFanAreNotDelayedByMediaWarmup(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);s.sampleFan(1,10,1,1000);s.sample(2,0,30,false,1000);s.sample(0,260,400,false,1100);s.sampleFan(1,10,0,1100);assertTrue(s.packet(1100)[7]>0);assertTrue(s.packet(1100)[8]>0);assertEquals(0,s.packet(1100)[9]);}
 @Test public void hvacPowerOffOverridesRememberedFanOne(){UltraComfortState s=new UltraComfortState();s.sampleFan(1,10,1,1000);s.sampleFan(1,10,0,1100);int event=s.packet(1100)[8];assertEquals(0,s.packet(1100)[3]);assertTrue(event>0);s.sampleFan(1,10,0,1200);assertEquals(event,s.packet(1200)[8]);assertEquals(2400,s.packet(1200)[11]);s.sampleFan(1,10,1,1300);assertEquals(1,s.packet(1300)[3]);assertTrue(s.packet(1300)[8]>event);}
 @Test public void initialHvacOffAndUnknownPowerDoNotInventEvents(){UltraComfortState s=new UltraComfortState();s.sampleFan(-1,10,0,1000);assertEquals(0,s.packet(1000)[3]);assertEquals(0,s.packet(1000)[8]);s.sampleFan(1,10,2,1100);assertEquals(0,s.packet(1100)[8]);assertEquals(-1,s.packet(1800)[3]);}
 @Test public void invalidOrStaleNeverRendersGuessedNumbers(){UltraComfortState s=new UltraComfortState();s.sample(1,2,10,false,1000);s.sample(1,3,10,false,1010);assertEquals(-1,s.packet(1800)[3]);assertEquals(0,s.packet(1800)[11]);s.sample(1,22,10,false,1800);assertEquals(-1,s.packet(1800)[3]);s.sample(1,4,10,false,1810);assertEquals(0,s.packet(1810)[8]);assertEquals(0,s.packet(1810)[11]);}
 @Test public void leavingUltraReseedsWithoutStalePopup(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);s.sample(0,260,400,false,1010);int old=s.packet(1010)[7];s.reset();assertEquals(-1,s.packet(1020)[2]);s.sample(0,270,400,false,2000);assertEquals(0,s.packet(2000)[7]);s.sample(0,275,400,false,2010);assertTrue(s.packet(2010)[7]>old);}
 @Test public void littleEndianPacketIsFixedSize(){UltraComfortState s=new UltraComfortState();s.sample(0,255,400,false,1000);byte[] b=UltraComfortState.bytes(s.packet(1000));assertEquals(64,b.length);assertEquals(1,b[0]);assertEquals(255,b[8]&255);assertEquals(0,b[9]);for(int i=52;i<64;i++)assertEquals(0,b[i]);}
}
